function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TaskManager' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with TaskManager(tasks).';
  const tasks = args[0][0];
  if (!Array.isArray(tasks) || tasks.length < 1 || tasks.length > 100000) return 'tasks holds 1 to 10^5 tasks.';
  if (operations.length - 1 > 200000) return 'At most 2 * 10^5 calls follow the constructor.';
  const isId = (v) => Number.isInteger(v) && v >= 0 && v <= 100000;
  const isPriority = (v) => Number.isInteger(v) && v >= 0 && v <= 1000000000;
  // The pool is a map from id to priority plus its (priority, id) keys kept sorted, so execTop is the last key.
  const live = new Map();
  const keys = [];
  const key = (taskId) => live.get(taskId) * 131072 + taskId;
  const find = (value) => { let low = 0, high = keys.length; while (low < high) { const mid = (low + high) >> 1; if (keys[mid] < value) low = mid + 1; else high = mid; } return low; };
  const insert = (taskId, priority) => { live.set(taskId, priority); const value = key(taskId); keys.splice(find(value), 0, value); };
  const remove = (taskId) => { keys.splice(find(key(taskId)), 1); live.delete(taskId); };
  for (const task of tasks) {
    if (!Array.isArray(task) || task.length !== 3) return 'Each task is [userId, taskId, priority].';
    if (!isId(task[0]) || !isId(task[1])) return 'userId and taskId are between 0 and 10^5.';
    if (!isPriority(task[2])) return 'priority is between 0 and 10^9.';
    if (live.has(task[1])) return 'The task ids in tasks must be different.';
    insert(task[1], task[2]);
  }
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'add') {
      if (a.length !== 3 || !isId(a[0]) || !isId(a[1]) || !isPriority(a[2])) return 'add takes userId and taskId (0 to 10^5) and priority (0 to 10^9).';
      if (live.has(a[1])) return `add uses task ${a[1]}, which is already in the pool.`;
      insert(a[1], a[2]);
    } else if (operations[i] === 'edit') {
      if (a.length !== 2 || !isId(a[0]) || !isPriority(a[1])) return 'edit takes taskId (0 to 10^5) and newPriority (0 to 10^9).';
      if (!live.has(a[0])) return `edit needs task ${a[0]} to be in the pool.`;
      remove(a[0]);
      insert(a[0], a[1]);
    } else if (operations[i] === 'rmv') {
      if (a.length !== 1 || !isId(a[0])) return 'rmv takes one taskId (0 to 10^5).';
      if (!live.has(a[0])) return `rmv needs task ${a[0]} to be in the pool.`;
      remove(a[0]);
    } else if (operations[i] === 'execTop') {
      if (a.length !== 0) return 'execTop takes no arguments.';
      if (keys.length > 0) remove(keys[keys.length - 1] % 131072);
    } else {
      return 'Only add, edit, rmv and execTop can follow the constructor.';
    }
  }
  return null;
}

