class TaskManager {
  constructor(tasks) {
    this.tasks = new Map();
    this.heap = [];
    for (const [userId, taskId, priority] of tasks) {
      this.add(userId, taskId, priority);
    }
  }

  add(userId, taskId, priority) {
    this.tasks.set(taskId, { userId, priority });
    this.push([priority, taskId]);
  }

  edit(taskId, newPriority) {
    this.tasks.get(taskId).priority = newPriority;
    this.push([newPriority, taskId]);
  }

  rmv(taskId) {
    this.tasks.delete(taskId);
  }

  execTop() {
    while (this.heap.length > 0) {
      const [priority, taskId] = this.pop();
      const task = this.tasks.get(taskId);
      if (task !== undefined && task.priority === priority) {
        this.tasks.delete(taskId);
        return task.userId;
      }
    }
    return -1;
  }

  before(a, b) {
    return a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
  }

  push(entry) {
    const heap = this.heap;
    heap.push(entry);
    let index = heap.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (!this.before(heap[index], heap[parent])) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  pop() {
    const heap = this.heap;
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let best = index;
      if (left < heap.length && this.before(heap[left], heap[best])) best = left;
      if (right < heap.length && this.before(heap[right], heap[best])) best = right;
      if (best === index) return top;
      [heap[best], heap[index]] = [heap[index], heap[best]];
      index = best;
    }
  }
}

