class TaskManager {
  constructor(tasks) {
    this.list = tasks.map(([userId, taskId, priority]) => ({ userId, taskId, priority }));
  }
  add(userId, taskId, priority) {
    this.list.push({ userId, taskId, priority });
  }
  edit(taskId, newPriority) {
    this.list.find(task => task.taskId === taskId).priority = newPriority;
  }
  rmv(taskId) {
    this.list = this.list.filter(task => task.taskId !== taskId);
  }
  execTop() {
    if (this.list.length === 0) return -1;
    // Sort by priority, then by task id, both from high to low, and run the first task.
    this.list.sort((a, b) => b.priority - a.priority || b.taskId - a.taskId);
    return this.list.shift().userId;
  }
}

