function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  // A crowded large case starts small and runs many tasks, so the pool empties and -1 appears.
  const crowded = large && rand() < 0.3;
  // Small cases use few ids, users and priorities, so ties and reused ids are common.
  const maxId = large ? 100000 : int(2, 8);
  const maxUser = large ? 100000 : int(0, 4);
  const maxPriority = large ? [5, 1000, 1000000000][int(0, 2)] : [1, 3, 1000000000][int(0, 2)];
  const n = large ? (crowded ? int(1, 60) : int(1500, 2000)) : int(1, Math.min(4, maxId + 1));
  // Distinct ids without a retry loop (the seeded generator can repeat itself): every small id, or a large
  // increasing run with random gaps, shuffled and cut to n.
  const ids = [];
  if (large) for (let id = int(0, 999); ids.length < 2000; id += 1 + int(0, 48)) ids.push(id);
  else for (let id = 0; id <= maxId; id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) {
    const j = int(0, i);
    [ids[i], ids[j]] = [ids[j], ids[i]];
  }
  const live = new Map();
  const retired = [];
  const tasks = [];
  for (const taskId of ids.slice(0, n)) {
    const userId = int(0, maxUser);
    const priority = int(0, maxPriority);
    live.set(taskId, priority);
    tasks.push([userId, taskId, priority]);
  }
  const operations = ['TaskManager'];
  const args = [[tasks]];
  const calls = large ? 499 : int(1, 12);
  const weights = crowded ? [0.2, 0.2, 0.1] : [0.25, 0.25, 0.15];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    let kind = roll < weights[0] ? 'add' : roll < weights[0] + weights[1] ? 'edit' : roll < weights[0] + weights[1] + weights[2] ? 'rmv' : 'execTop';
    if ((kind === 'edit' || kind === 'rmv') && live.size === 0) kind = 'add';
    if (kind === 'add') {
      let taskId = -1;
      for (let tries = 0; tries < 20 && taskId === -1; tries++) {
        const pick = retired.length > 0 && rand() < 0.4 ? retired[int(0, retired.length - 1)] : int(0, maxId);
        if (!live.has(pick)) taskId = pick;
      }
      if (taskId === -1) kind = 'execTop';
      else {
        const priority = int(0, maxPriority);
        live.set(taskId, priority);
        operations.push('add');
        args.push([int(0, maxUser), taskId, priority]);
      }
    }
    if (kind === 'edit' || kind === 'rmv') {
      const ids = [...live.keys()];
      const taskId = ids[int(0, ids.length - 1)];
      if (kind === 'edit') {
        // Sometimes keep the same priority, which leaves two identical entries in a lazy heap.
        const priority = rand() < 0.15 ? live.get(taskId) : int(0, maxPriority);
        live.set(taskId, priority);
        operations.push('edit');
        args.push([taskId, priority]);
      } else {
        live.delete(taskId);
        retired.push(taskId);
        operations.push('rmv');
        args.push([taskId]);
      }
    }
    if (kind === 'execTop') {
      let top = -1;
      for (const [taskId, priority] of live) {
        if (top === -1 || priority > live.get(top) || (priority === live.get(top) && taskId > top)) top = taskId;
      }
      if (top !== -1) {
        live.delete(top);
        retired.push(top);
      }
      operations.push('execTop');
      args.push([]);
    }
  }
  return [operations, args];
}
